// Симуляция на условных баллах: как шум влияет на качество ответа
function answerQuality(contextDocs) {
  const hasRelevant = contextDocs.includes('theme-config.js');
  let score = hasRelevant ? 95 : 30;
  const noise = contextDocs.length - (hasRelevant ? 1 : 0);
  score -= noise * 6; // каждый лишний файл отвлекает внимание
  return Math.max(score, 5);
}

console.log('только нужный файл:', answerQuality(['theme-config.js']));
console.log('нужный + 1 лишний:', answerQuality(['theme-config.js', 'package.json']));
