];

function packForTask(docs) {
  const kept = docs.filter((d) => d.relevant);
  const dropped = docs.filter((d) => !d.relevant);
  const keptChars = kept.reduce((sum, d) => sum + d.chars, 0);
  const allChars = docs.reduce((sum, d) => sum + d.chars, 0);
  return {
    keptNames: kept.map((d) => d.name),
    droppedCount: dropped.length,
    savedChars: allChars - keptChars,
  };
}

const result = packForTask(docs);
