function retrieve(query, files, k) {
  const words = query.toLowerCase().split(' ');
  const ranked = files
    .map((f) => ({
      path: f.path,
      score: words.filter((w) => f.text.toLowerCase().split(' ').includes(w)).length,
    }))
    .filter((f) => f.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, k)
    .map((f) => f.path);
  return ranked;
}

