// Контекст-пакер: запуск локально командой node packer.js
// Всё детерминировано: мок-проект, без сети и API-ключей.
const project = {
  packageJson: '{"name":"app","dependencies":{"react":"18"},"scripts":{"test":"vitest"}}',
  tree: 'src/App.jsx src/theme.js src/api/users.js src/utils/date.js',
  files: [
    { path: 'src/App.jsx', text: 'компонент приложение роутер меню' },
    { path: 'src/theme.js', text: 'тема dark light класс body localStorage' },
    { path: 'src/api/users.js', text: 'api users fetch список' },
    { path: 'src/utils/date.js', text: 'дата формат утилита' },
  ],
};

const TASK = 'тёмная тема';
const BUDGET = 70; // токенов; оценка ≈ 1 токен на 4 символа
const estimate = (s) => Math.ceil(s.length / 4);

function score(query, text) {
  const words = query.split(' ');
  return words.filter((w) => text.includes(w)).length;
}

const parts = [
  { label: 'instructions', text: 'Ты помощник по коду. Правь только файлы из пакета.', must: true },
  { label: 'package.json', text: project.packageJson, must: true },
  { label: 'tree', text: project.tree, must: true },
];

const ranked = project.files
  .map((f) => ({ f: f, s: score(TASK, f.path + ' ' + f.text) }))
  .sort((a, b) => b.s - a.s);
ranked.forEach(({ f, s }) => parts.push({ label: f.path, text: f.path + ' ' + f.text, must: false, score: s }));
parts.push({ label: 'summary', text: 'Прочие файлы к задаче темы не относятся.', must: true });

const included = [];
const excluded = [];
let used = 0;

for (const p of parts) {
  const cost = estimate(p.text);
  const fits = used + cost <= BUDGET;
  if (p.must && !fits) {
    excluded.push(p.label + ' — обязательное, но не влезло (увеличьте бюджет)');
  } else if (p.must || (p.score > 0 && fits)) {
    included.push(p.label + ' (' + cost + ' токенов)');
    used += cost;
  } else {
    const reason = p.score === 0 ? 'нерелевантен' : 'не хватило бюджета';
    excluded.push(p.label + ' — ' + reason);
  }
}

console.log('Задача: ' + TASK);
console.log('Включено:');
included.forEach((i) => console.log(' + ' + i));
console.log('Исключено:');
excluded.forEach((e) => console.log(' - ' + e));
console.log('Использовано токенов: ' + used + ' из ' + BUDGET);
